:root {
  color-scheme: light;
  --bg: #f5f6f8;
  --panel-bg: #ffffff;
  --border: #d7dbe0;
  --text: #1f2328;
  --muted: #57606a;
  --primary: #2563eb;
  --primary-hover: #1d4ed8;
  --success-bg: #e6f6ec;
  --success-text: #166534;
  --error-bg: #fdecea;
  --error-text: #b42318;
  --info-bg: #eaf1fd;
  --info-text: #1e429f;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  line-height: 1.5;
}

.app {
  max-width: 720px;
  margin: 0 auto;
  padding: 2rem 1.25rem 4rem;
}

.app-header h1 {
  font-size: 1.5rem;
  margin: 0 0 0.25rem;
}

.subtitle {
  margin: 0 0 1.5rem;
  color: var(--muted);
}

.status {
  margin: 0 0 1.5rem;
  padding: 0.75rem 1rem;
  border-radius: 6px;
  font-weight: 500;
}

.status-info {
  background: var(--info-bg);
  color: var(--info-text);
}

.status-success {
  background: var(--success-bg);
  color: var(--success-text);
}

.status-error {
  background: var(--error-bg);
  color: var(--error-text);
}

.panel {
  background: var(--panel-bg);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 1.25rem 1.5rem;
  margin: 0 0 1.5rem;
}

.panel[disabled] {
  opacity: 0.55;
}

.panel h2,
.panel legend {
  font-size: 1rem;
  font-weight: 600;
  margin: 0 0 1rem;
  padding: 0;
}

.field {
  margin-bottom: 0.9rem;
}

.field:last-child {
  margin-bottom: 0;
}

.field label {
  display: block;
  font-size: 0.85rem;
  font-weight: 500;
  color: var(--muted);
  margin-bottom: 0.3rem;
}

.field input,
.field textarea {
  width: 100%;
  padding: 0.5rem 0.6rem;
  border: 1px solid var(--border);
  border-radius: 6px;
  font: inherit;
  color: var(--text);
  background: var(--panel-bg);
}

.field input:focus,
.field textarea:focus {
  outline: 2px solid var(--primary);
  outline-offset: 1px;
}

.field textarea {
  resize: vertical;
}

.pdf-entries {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.pdf-entry {
  border-top: 1px solid var(--border);
  padding-top: 1rem;
}

.pdf-entry:first-child {
  border-top: none;
  padding-top: 0;
}

.pdf-entry-filename {
  font-size: 0.95rem;
  font-family: ui-monospace, SFMono-Regular, Consolas, monospace;
  margin: 0 0 0.75rem;
  word-break: break-all;
}

button.primary {
  background: var(--primary);
  color: #fff;
  border: none;
  border-radius: 6px;
  padding: 0.6rem 1.1rem;
  font: inherit;
  font-weight: 600;
  cursor: pointer;
}

button.primary:hover:not(:disabled) {
  background: var(--primary-hover);
}

button.primary:disabled {
  background: #a7b6d6;
  cursor: not-allowed;
}

