const CDP_PORT = 9333;
const TARGET_URL = 'http://localhost:5195/debug-test.html';

async function main() {
  const res = await fetch(`http://localhost:${CDP_PORT}/json/new?${encodeURIComponent(TARGET_URL)}`, { method: 'PUT' });
  const target = await res.json();
  const wsUrl = target.webSocketDebuggerUrl;
  console.log('Target ws:', wsUrl);

  const ws = new WebSocket(wsUrl);
  let id = 1;
  const pending = new Map();

  function send(method, params = {}) {
    const msgId = id++;
    ws.send(JSON.stringify({ id: msgId, method, params }));
    return new Promise((resolve) => pending.set(msgId, resolve));
  }

  await new Promise((resolve, reject) => {
    ws.addEventListener('open', resolve);
    ws.addEventListener('error', reject);
  });

  ws.addEventListener('message', (event) => {
    const msg = JSON.parse(event.data);
    if (msg.id && pending.has(msg.id)) {
      pending.get(msg.id)(msg.result);
      pending.delete(msg.id);
      return;
    }
    if (msg.method === 'Runtime.consoleAPICalled') {
      const args = msg.params.args.map(a => a.value ?? a.description ?? '').join(' ');
      console.log(`[console.${msg.params.type}]`, args);
    } else if (msg.method === 'Runtime.exceptionThrown') {
      console.log('[exception]', JSON.stringify(msg.params.exceptionDetails));
    }
  });

  await send('Runtime.enable');
  await send('Network.enable');
  console.log('Listening... waiting 10s');
  await new Promise((r) => setTimeout(r, 10000));
  ws.close();
  process.exit(0);
}

main().catch((err) => {
  console.error('Script failed:', err);
  process.exit(1);
});

