  // `destroy()` lives on the loadingTask returned by getDocument(), not on
  // the resolved PDFDocumentProxy (`pdf.destroy` does not exist and throws).
  const loadingTask = pdfjsLib.getDocument({ data: await file.arrayBuffer() });
