import { extractPdfMetadata } from '/src/pdfMetadata.js';
import * as pdfjsLib from 'pdfjs-dist';

async function dumpRaw(file) {
  const loadingTask = pdfjsLib.getDocument({ data: await file.arrayBuffer() });
  try {
    const pdf = await loadingTask.promise;
    const { info, metadata } = await pdf.getMetadata();
    const xmp = metadata ? metadata.getAll() : null;
    console.log('DEBUG_RAW', file.name, 'info=', JSON.stringify(info), 'xmp=', JSON.stringify(xmp));
  } finally {
    await loadingTask.destroy();
  }
}

async function run() {
  console.log('DEBUG: run() started');
  const names = [
    'KAYT_2014_258_book.pdf',
    'KAYT_2014_260_text.pdf',
    'LO_Sea_Creatures_first_language.pdf',
    'Mi-Tjiwilirr i Wulumen Tulh.pdf',
    'NG_Whats_this_Eng.pdf',
    'an0022_crocodile.pdf',
    'gu0001_baleh.pdf',
    'pi0004_maku_maku.pdf',
  ];
  const results = [];
  for (const name of names) {
    const t0 = performance.now();
    console.log('DEBUG: fetching', name);
    try {
      const res = await fetch('/pdf-files/' + encodeURIComponent(name));
      console.log('DEBUG: fetch status', name, res.status);
      const blob = await res.blob();
      const file = new File([blob], name, { type: 'application/pdf' });
      await dumpRaw(file);
      console.log('DEBUG: calling extractPdfMetadata', name);
      const meta = await extractPdfMetadata(file);
      console.log('DEBUG: extractPdfMetadata resolved', name, JSON.stringify(meta));
      results.push({ name, meta, ms: performance.now() - t0 });
    } catch (err) {
      console.log('DEBUG: ERROR', name, String(err), err && err.stack);
      results.push({ name, error: String(err), ms: performance.now() - t0 });
    }
  }
  console.log('DEBUG_RESULTS_JSON: ' + JSON.stringify(results));
  document.title = 'DONE';
}
run();

