  root.innerHTML = `
    <div class="app">
      <header class="app-header">
        <h1>RO-Crate PDF Packaging Tool</h1>
        <p class="subtitle">Package a folder of PDFs into an RO-Crate 1.3 dataset.</p>
      </header>

      <div id="status" class="status" role="status" aria-live="polite" hidden></div>

