const CDP_PORT = 9334;
const TARGET_URL = 'http://localhost:5196/index.html';

async function main() {
  const res = await fetch(`http://localhost:${CDP_PORT}/json/new?${encodeURIComponent(TARGET_URL)}`, { method: 'PUT' });
  const target = await res.json();
  const ws = new WebSocket(target.webSocketDebuggerUrl);
  let id = 1;
  const pending = new Map();
  function send(method, params = {}) {
    const msgId = id++;
    ws.send(JSON.stringify({ id: msgId, method, params }));
    return new Promise((resolve) => pending.set(msgId, resolve));
  }
  await new Promise((resolve, reject) => {
    ws.addEventListener('open', resolve);
    ws.addEventListener('error', reject);
  });
  ws.addEventListener('message', (event) => {
    const msg = JSON.parse(event.data);
    if (msg.id && pending.has(msg.id)) {
      pending.get(msg.id)(msg.result);
      pending.delete(msg.id);
      return;
    }
    if (msg.method === 'Runtime.consoleAPICalled') {
      const args = msg.params.args.map(a => a.value ?? a.description ?? '').join(' ');
      console.log(`[console.${msg.params.type}]`, args);
    } else if (msg.method === 'Runtime.exceptionThrown') {
      console.log('[exception]', JSON.stringify(msg.params.exceptionDetails));
    }
  });
  await send('Runtime.enable');
  await new Promise((r) => setTimeout(r, 1500));

  // 1. Check default datePublished value equals today's date (UTC ISO).
  const evalResult1 = await send('Runtime.evaluate', {
    expression: `document.getElementById('collection-date-published').value`,
    returnByValue: true,
  });
  console.log('datePublished default value:', JSON.stringify(evalResult1.result.value));
  console.log('expected (today UTC):', new Date().toISOString().slice(0, 10));

  // 2. Simulate files loaded (bypass real directory picker) by directly
  //    exercising the exported handleGenerate path is not possible from
  //    outside the module, so instead check that the Generate button and
  //    fieldsets exist and are initially disabled, and that the status
  //    element + field ids used by focusCollectionField all exist.
  const evalResult2 = await send('Runtime.evaluate', {
    expression: `JSON.stringify({
      collectionDisabled: document.getElementById('collection-fieldset').disabled,
      pdfDisabled: document.getElementById('pdf-fieldset').disabled,
      generateDisabled: document.getElementById('generate-btn').disabled,
      hasDatePublishedInput: !!document.getElementById('collection-date-published'),
      nameValue: document.getElementById('collection-name').value,
    })`,
    returnByValue: true,
  });
  console.log('shell state:', evalResult2.result.value);

  ws.close();
  process.exit(0);
}

main().catch((err) => {
  console.error('Script failed:', err);
  process.exit(1);
});

