1	import { ROCrate } from 'ro-crate';
2	
3	// Verified against the installed ro-crate 3.7.2 source: a bare `new ROCrate()`
4	// defaults to RO-Crate 1.2. Seeding the constructor with our own @context and
5	// @graph (rather than patching afterwards) produces the exact required
6	// RO-Crate 1.3 @context/conformsTo with no further correction needed.
7	const RO_CRATE_CONTEXT_URL = 'https://w3id.org/ro/crate/1.3/context';
8	const RO_CRATE_CONFORMS_TO_URL = 'https://w3id.org/ro/crate/1.3';
9	
10	/**
11	 * Build an RO-Crate from reviewed collection and per-PDF metadata.
12	 * Assumes collection.name, .description, .license, and .datePublished have
13	 * already been validated as non-blank by the caller (see main.js).
14	 * @param {{ collection: {name: string, description: string, license: string, datePublished: string},
15	 *           files: Array<{name: string, title: string, author: string, date: string, description: string}> }} input
16	 * @returns {ROCrate}
17	 */
18	export function buildCrate({ collection, files }) {
19	  const seed = {
20	    '@context': RO_CRATE_CONTEXT_URL,
21	    '@graph': [
22	      { '@id': './', '@type': 'Dataset' },
23	      {
24	        '@id': 'ro-crate-metadata.json',
25	        '@type': 'CreativeWork',
26	        about: { '@id': './' },
27	        conformsTo: { '@id': RO_CRATE_CONFORMS_TO_URL },
28	      },
29	    ],
30	  };
31	
